(function(){
var ST=window.ST,BA=ST.BA,FV=window.FV,esc=ST.esc,$=ST.$,staff=ST.staff;if(!staff||!$('app'))return;
var id=BA.qs.get('id'),q=FV.queue().filter(function(x){return x.id===id})[0],p=FV.property(id);
if(!q||!p){$('app').innerHTML=ST.head('Report not found','This site report is not in the queue.','<a class="btn" href="checker.html">Back to checker work</a>');return}
var own=staff.id&&staff.id===q.eng,done=q.status==='approved',ret=q.status==='returned',a=FV.asg()[id]||{},hrs=a.at?Math.round((q.subAt-a.at)/36e5*10)/10:null;
function pic(k,n){return '<a href="#" data-idb="'+esc(k)+'" target="_blank" rel="noopener" style="display:block;border-radius:10px;overflow:hidden;aspect-ratio:4/3;background:#ddd">'+BA.im(k,'width:100%;height:100%;object-fit:cover')+'</a>'}
function fileRow(n,k,t){return '<div class="doc"><span><b>'+esc(n)+'</b></span><a class="btn out sm" target="_blank" rel="noopener" data-idb="'+esc(k)+'" href="#">Open ↗</a></div>'}
var dsmP=FV.dsmOf(p),eng0=FV.get(q.eng);
var asgHtml='<div style="border:1px solid var(--line);border-radius:12px;padding:12px;margin:0 0 12px"><b>Team on this property</b><p style="margin:6px 0 0;font-size:13.5px">District Sales Manager: <b>'+(dsmP?esc(dsmP.name)+'</b> ('+esc(BA.districtOf(p))+')':'<span style="color:#A50E0E">none registered for '+esc(BA.districtOf(p))+'. Ask admin to add one.</span>')+'<br>Field verification engineer: <b>'+esc(eng0?eng0.name:q.engName)+'</b>'+(eng0&&eng0.manager!==(dsmP||{}).id?' <span style="color:#A50E0E">does not report to this manager</span>':'')+'</p></div>';
var lms=q.landmarks.filter(function(x){return x.name&&+x.km>0}).sort(function(x,y){return x.km-y.km});
function render(){
 $('app').innerHTML='<p style="margin:0 0 6px"><a href="checker.html" style="color:var(--rose);font-weight:700">← Checker work</a></p>'+ST.head('Review site report · '+esc(p.short)+', '+esc(p.loc),esc(p.bank)+' · '+esc(FV.cl(p.city))+' · Property '+p.id+'. Submitted by '+esc(q.engName)+' on '+esc(FV.when(q.subAt))+(hrs!=null?' ('+hrs+' h after assignment'+(hrs>48?', late':'')+')':'')+'.',(done?ST.chip('Approved and published','g'):ret?ST.chip('Returned to engineer','r'):ST.chip('Waiting for you','a')))+
 '<div class="lwg" style="grid-template-columns:minmax(0,1.5fr) minmax(0,1fr)"><div>'+
 ST.panel('Photographs ('+q.photos.length+')','<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">'+q.photos.map(function(x){return pic(x.k)}).join('')+'</div>')+
 ST.panel('Video tour',q.video?'<video controls preload="metadata" playsinline '+(q.video.k.indexOf('idb:')===0?'data-idb="'+esc(q.video.k)+'"':'src="'+esc(q.video.k)+'"')+' style="width:100%;border-radius:12px;background:#000;max-height:380px"></video><p style="color:var(--mute);font-size:13px;margin:6px 0 0">'+esc(q.video.n)+'</p>':'<p style="color:var(--mute)">No video was added.</p>')+
 ST.panel('Documents','<h3 style="font:800 14px var(--f);margin:0 0 6px">Latest EC ('+(q.ec||[]).length+')</h3>'+((q.ec||[]).length?'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:12px">'+q.ec.map(function(x){return x.t==='application/pdf'?'<div class="doc" style="grid-column:span 2"><span><b>'+esc(x.n)+'</b></span><a class="btn out sm" target="_blank" data-idb="'+esc(x.k)+'" href="#">Open PDF ↗</a></div>':pic(x.k)}).join('')+'</div>':'<p style="color:#A50E0E">No EC attached.</p>')+'<h3 style="font:800 14px var(--f);margin:0 0 6px">Sale deed ('+q.deed.length+')</h3>'+(q.deed.length?'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:12px">'+q.deed.map(function(x){return x.t==='application/pdf'?'<div class="doc" style="grid-column:span 2"><span><b>'+esc(x.n)+'</b></span><a class="btn out sm" target="_blank" data-idb="'+esc(x.k)+'" href="#">Open PDF ↗</a></div>':pic(x.k)}).join('')+'</div>':'<p style="color:var(--mute)">None.</p>')+'<h3 style="font:800 14px var(--f);margin:8px 0 6px">Other bank documents ('+q.docs.length+')</h3>'+(q.docs.length?q.docs.map(function(x){return fileRow(x.title+' · '+x.n,x.k)}).join(''):'<p style="color:var(--mute)">None.</p>'))+
 '</div><div>'+
 ST.panel('Valuation','<div class="facts2" style="grid-template-columns:1fr 1fr"><div><small>Bank reserve price</small><b>'+BA.inr(p.reserve)+'</b></div><div><small>Market value (engineer)</small><b>'+BA.inr(+q.mv)+'</b></div><div><small>Recommended fair price</small><b>'+BA.inr(+q.fair)+'</b></div><div><small>Fair price vs reserve</small><b>'+(+q.fair>=p.reserve?'+':'−')+Math.abs(Math.round((q.fair/p.reserve-1)*100))+'%</b></div></div>'+(+q.fair>+q.mv?'<p style="color:#A50E0E;margin:10px 0 0"><b>Check this:</b> the fair price is above the market value.</p>':''))+
 ST.panel('Location','<p style="margin:0 0 6px"><b>GPS</b> '+esc(Number(q.gps.lat).toFixed(5)+', '+Number(q.gps.lng).toFixed(5))+(q.gps.acc?' · about '+Math.round(q.gps.acc)+' m accuracy':'')+'</p><p style="margin:0 0 10px"><a href="'+esc(q.maps)+'" target="_blank" rel="noopener">Open in Google Maps ↗</a></p><h3 style="font:800 14px var(--f);margin:0 0 6px">Landmarks</h3><ul style="margin:0;padding-left:18px">'+lms.map(function(x){return '<li>'+esc(x.km)+' km from '+esc(x.name)+(x===lms[0]?' <small style="color:var(--mute)">(shown to free users)</small>':'')+'</li>'}).join('')+'</ul>')+
 ST.panel('Positives, negatives and premium check','<div class="facts2" style="grid-template-columns:1fr 1fr"><div><small>Positives</small><b style="font-size:14px;white-space:pre-line">'+esc(q.pos||'—')+'</b></div><div><small>Negatives</small><b style="font-size:14px;white-space:pre-line">'+esc(q.neg||'—')+'</b></div></div><p style="margin:10px 0 0"><b>Engineer suggests premium for:</b> '+((q.prem||[]).length?esc(q.prem.join(', ')):'nothing')+(q.premNote?' · '+esc(q.premNote):'')+'<br><b>Near an avoid-list item:</b> '+((q.nearBad||[]).length?'<span style="color:#A50E0E">'+esc(q.nearBad.join(', '))+'</span>':'none')+'</p>')+
 ST.panel('Site observations','<div class="facts2" style="grid-template-columns:1fr 1fr"><div><small>Occupancy</small><b>'+esc(q.occ||'—')+'</b></div><div><small>Access road</small><b>'+esc(q.access||'—')+'</b></div><div><small>Boundaries match</small><b>'+esc(q.boundary||'—')+'</b></div><div><small>Structure (1 to 5)</small><b>'+esc(q.cond||'—')+'</b></div></div><p style="margin:10px 0 0"><b>Utilities:</b> '+(q.util.length?esc(q.util.join(', ')):'none noted')+'<br><b>Litigation or notices:</b> '+esc(q.lit||'None seen')+'<br>'+esc(q.notes||'')+'</p>')+
 (done?ST.panel('Published','<p style="margin:0 0 10px">This report is live on the property page.</p>'+((FV.pasg(id)||{}).mkt?'<p style="margin:0 0 10px"><b>District Sales Manager:</b> '+esc((FV.get((FV.pasg(id)||{}).mkt)||{}).name||(FV.pasg(id)||{}).mkt)+'<br><b>Field verification engineer:</b> '+esc((FV.get((FV.pasg(id)||{}).fe)||{}).name||(FV.pasg(id)||{}).fe)+'</p>':'')+'<a class="btn" href="property.html?id='+id+'&sv=1" target="_blank">Open the listing ↗</a>'):
  ST.panel('Your decision',own?'<div class="ok" style="background:#FFF1D6;color:#8A5A00;margin-bottom:10px">You submitted this report, so another checker has to approve it. This keeps every published report checked by a second person.</div>':'<div class="cks" style="display:grid;gap:8px;margin-bottom:12px"><label><input type="checkbox" class="ck"> Photographs and video match the property</label><label><input type="checkbox" class="ck"> Sale deed and documents are readable</label><label><input type="checkbox" class="ck"> Latest EC is attached and readable</label><label><input type="checkbox" class="ck"> Valuation, GPS and landmarks look right</label></div><label style="display:flex;gap:8px;align-items:center;margin-bottom:12px"><input type="checkbox" id="lp"'+((q.prem||[]).length&&!(q.nearBad||[]).length?' checked':'')+'> List this property in the Premium section</label>'+asgHtml+'<label class="form" style="max-width:none">Comments to the engineer <small style="color:var(--mute)">required if you return it</small><textarea id="cmt" rows="3"></textarea></label><div class="ac" style="margin-top:12px"><button class="btn" id="apv" disabled style="opacity:.45">Approve and publish</button><button class="btn out" id="rtn">Return to engineer</button></div>'))+
 ST.panel('History',q.hist.slice().reverse().map(function(h){return '<div style="margin-bottom:8px"><b>'+esc(h.what)+'</b><br><small style="color:var(--mute)">'+esc(h.who)+' · '+esc(FV.when(h.at))+'</small></div>'}).join(''))+
 '</div></div>';
 BA.hydrate($('app'));
 var cks=[].slice.call(document.querySelectorAll('.ck'));function upd(){var ok=cks.length&&cks.every(function(c){return c.checked})&&!!dsmP;if($('apv')){$('apv').disabled=!ok;$('apv').style.opacity=ok?1:.45}}
 cks.forEach(function(c){c.onchange=upd});upd()
 if($('apv'))$('apv').onclick=function(){if(FV.approve(id,staff,!!($('lp')&&$('lp').checked))){ST.log('Approved field report '+id);BA.toast('Approved and published on the property page');q=FV.queue().filter(function(x){return x.id===id})[0];done=true;render()}};
 if($('rtn'))$('rtn').onclick=function(){var n=($('cmt').value||'').trim();if(n.length<5){BA.toast('Tell the engineer what to fix');$('cmt').focus();return}FV.sendBack(id,staff,n);ST.log('Returned field report '+id);BA.toast('Returned to '+q.engName);location.href='checker.html'}}
render();
})();
